/**
 * @param {number} n
 * @param {number} limit
 * @return {number}
 */
var distributeCandies = function(n, limit) {
    function c2(x) {
        if (x < 0) return 0;
        return ((x + 2) * (x + 1)) / 2;
    }
    const L = limit + 1;
    return c2(n) - 3 * c2(n - L) + 3 * c2(n - 2 * L) - c2(n - 3 * L);
};
